   130→	public ProductNameTokenizer(AttributeFactory factory) {
   131→		super(factory);
   132→	}
   133→
   134→	protected boolean isTokenChar(int c1, int c2) {
   135→		return !Character.isWhitespace(c1);
   136→	}
   137→
   138→	@Override
   139→	public final boolean incrementToken() throws IOException {
   140→		typeAtt.setType(null);
   141→		logger.trace("INCREMENT-TOKEN");
   142→		int length = 0;
   143→		int start = -1;
   144→		int end = -1;
   145→		int bufferStart = position;
   146→		boolean continueTerm = false;
   147→		int startOffset = 0;
   148→		int endOffset = 0;
   149→		while (!tokenAtt.isState(TokenInfoAttribute.STATE_INPUT_FINISHED)) {
   150→			if (entry == null) {
   151→				while (true) {
   152→					if (position >= readLength) {
   153→						////////////////////////////////////////////////////////////////////////////////
   154→						// 1. 원본 읽어오기 (버퍼 크기만큼 읽어옴)
   155→						// 읽어온 버퍼가 없거나 모두 처리한 상태라면  리더에서 읽어온다.
   156→						////////////////////////////////////////////////////////////////////////////////
   157→						char[] oldBuffer = backBuffer[0];
   158→						char[] newBuffer = backBuffer[1];
   159→						backBuffer[0] = newBuffer;
   160→						backBuffer[1] = oldBuffer;
   161→						baseOffset += readLength;
   162→						readLength = input.read(newBuffer, 0, newBuffer.length);
   163→						logger.trace("READ {}/{}", newBuffer.length, readLength);
   164→						if (readLength > 0) {
   165→							buffer = newBuffer;
   166→							tokenAtt.ref(newBuffer, 0, 0);
   167→							tokenAtt.rmState(TokenInfoAttribute.STATE_INPUT_BUFFER_EXHAUSTED);
   168→							entry = null;
   169→							for (tokenLength = readLength; tokenLength > 0; tokenLength--) {
   170→								if (getType(newBuffer[tokenLength - 1]) != WHITESPACE) {
   171→									break;
   172→								}
   173→							}
   174→						} else {
   175→							readLength = 0;
   176→							logger.trace("LENGTH:{} / {}", length, readLength);
   177→							if (length > 0) {
   178→								break;
   179→							} else {
   180→								finalOffset = correctOffset(baseOffset);
   181→								logger.trace("TOKENIZER STOPPED!!");
   182→								tokenAtt.addState(TokenInfoAttribute.STATE_INPUT_FINISHED);
   183→								return false;
   184→							}
   185→						}
   186→						if (tokenLength > 0 && tokenLength < FULL_TERM_LENGTH && baseOffset == 0) {
   187→							// FULL-TERM. 색인시에는 추출하지 않음 (필터에서 걸러짐)
   188→							tokenAtt.ref(newBuffer, 0, tokenLength);
   189→							tokenAtt.posTag(null);
   190→							offsetAtt.setOffset(0, tokenLength);
   191→							typeAtt.setType(FULL_STRING);
   192→							return true;
   193→						}
   194→						position = 0;
   195→						bufferStart = 0;
   196→						chrCurrent = 0;
   197→						typeCurrent = null;
   198→					}
   199→					{
   200→						////////////////////////////////////////////////////////////////////////////////
   201→						// 2. 버퍼 내 단순 토크닝 (공백 / 특수기호에 의한 분해)
   202→						////////////////////////////////////////////////////////////////////////////////
   203→						char chrPrev = chrCurrent;
   204→						String typePrev = typeCurrent;
   205→						chrCurrent = buffer[position];
   206→						typeCurrent = getType(chrCurrent);
   207→						position ++;
   208→						int pass = 1;
   209→
   210→						if (typePrev == null) {
   211→							// 이전문자가 없다면 패스
   212→						} else if (typePrev == WHITESPACE && typeCurrent != WHITESPACE) {
   213→							// 
   214→						} else if (typePrev == WHITESPACE && typeCurrent == WHITESPACE) {
   215→							// 공백뒤 공백. 오프셋 위치 변경
   216→							pass = 2;
   217→						} else if (typePrev != WHITESPACE && typeCurrent == WHITESPACE) {
   218→							// 일반문자 뒤 공백. 끊어줌.
   219→							pass = 0;
   220→						} else if (typePrev != typeCurrent) {
   221→							// 2021.06.23
   222→							// 토크닝 수준에서 일부 떨어지고 일부 붙어서 오분석이 나오기 때문에
   223→							// 모두 떨어뜨려서 한글분석을 거침
   224→							// 2021.04.26 swsong
   225→							// 숫자+단위명 조합은 parsingRule에서 다시한번 확인하므로 여기서는 떨어져있어도 무방.
   226→							// 오히려 v12배터리팩 같은 경우, 한글이 분리가 안되는 부작용이 발생하여 떨어지도록 수정.
   227→							pass = 0;
   228→						}
   229→						// logger.trace("CH:{}[{}] / {} / {} / {} / {}", chrCurrent, typeCurrent, typePrev, position, length, pass);
   230→						if (pass == 1) {
   231→							// 최초 토크닝 위치 결정
   232→							if (length == 0) {
   233→								assert start == -1;
   234→								start = baseOffset + position - 1;
   235→								end = start;
   236→							}
   237→							end ++;
   238→							length++;
   239→							// 버퍼 마지막인 경우 무조건 끊어줌 (15키 등)
   240→							if (position >= tokenLength) {
   241→								break;
   242→							}
   243→						} else if (pass == 2) {
   244→							// 공백 건너뜀
   245→							bufferStart = position;
   246→							continue;
   247→						} else if (length > 0) {
   248→							// 토크닝 길이 결정
   249→							if (position >= tokenLength) {
   250→								position++;
   251→							}
   252→							if (typePrev != WHITESPACE && typeCurrent == WHITESPACE) {
   253→								position--; 
   254→							} else if (typePrev != WHITESPACE && typeCurrent != WHITESPACE) {
   255→								position--; 
   256→							}
   257→							length = position - bufferStart;
   258→							break;
   259→						}
   260→					}
   261→				}
   262→
   263→				assert start != -1;
   264→				startOffset = correctOffset(start);
   265→				endOffset = correctOffset(end);
   266→
   267→				if (extractor != null) {
   268→					logger.trace("TOKEN:{} / {}~{} / {}", new CharVector(buffer, bufferStart, length), position - bufferStart, length);
   269→					extLength = length;
   270→					if (extLength > extractor.getTabularSize()) {
   271→						extLength = extractor.getTabularSize();
   272→						tabularFull = true;
   273→					} else {
   274→						tabularFull = false;
   275→					}
   276→					logger.trace("EXTRACT:{} / {}~{} / {}", new CharVector(buffer, bufferStart, extLength), bufferStart, extLength, baseOffset);
   277→					extractor.setInput(buffer, bufferStart, extLength);
   278→					entry = extractor.extract();
   279→					continue;
   280→				} else {
   281→					// 한글분석기가 없는경우 (한글사전 적재 실패) 분해된 토큰으로만 출력
   282→					tokenAtt.ref(buffer, bufferStart, length);
   283→					offsetAtt.setOffset(startOffset, finalOffset = endOffset);
   284→					logger.trace("TOKEN:{} / {}~{}", tokenAtt.ref(), startOffset, endOffset);
   285→				}
   286→			} else {
   287→				while (entry != null) {
   288→					////////////////////////////////////////////////////////////////////////////////
   289→					// 3. 한글분해
   290→					////////////////////////////////////////////////////////////////////////////////
   291→					// 분해된 한글이 있으므로 속성에 출력해 준다
   292→					if (entry.column() <= 0) {
   293→						entry = entry.next();
   294→						continue;
   295→					}
   296→					startOffset = correctOffset(baseOffset + entry.offset());
   297→					endOffset = correctOffset(baseOffset + entry.offset() + entry.column());
   298→					tokenAtt.ref(buffer, entry.offset(), entry.column());
   299→					tokenAtt.posTag(entry.posTag());
   300→					offsetAtt.setOffset(startOffset, endOffset);
   301→					logger.trace("TERM:{} / {}~{} / {} / {} / {}", tokenAtt.ref(), startOffset, endOffset, baseOffset, readLength, tokenAtt.posTag());
   302→					if (exportTerm) {
   303→						if (logger.isTraceEnabled()) {
   304→							logger.trace("{} / {}~{}", new String(buffer, entry.offset(), entry.column()), entry.offset(), entry.column());
   305→						}
   306→						termAtt.copyBuffer(buffer, entry.offset(), entry.column());
   307→					}
   308→					int extPosition = entry.offset() + entry.column();
   309→					int prevOffset = entry.offset();
   310→					entry = entry.next();
   311→					// ※ 분석기에서 오분석이 나는경우 (분리어사전 적용시 이전 오프셋으로 되돌아 가는 버그)
   312→					while (entry != null) {
   313→						if (entry.offset() < prevOffset) { 
   314→							entry = entry.next(); 
   315→						} else {
   316→							break;
   317→						}
   318→					}
   319→
   320→					if (entry == null) {
   321→						// 분해된 한글이 없다면 다음구간 한글분해 시도
   322→						if (extPosition < position) {
   323→							if (tabularFull) {
   324→								// TabularSize 를 넘어서 분석한 후 경우의 수
   325→								// 1. 일반적으로 최종 단어와 이후 단어를 이어서 다시한번 단어분석 시도
   326→								// 2. 분석된 단어길이가 tabularsize 와 같은경우 -> 그대로 출력 (Rule 에서 결합시도)
   327→								logger.trace("CONTINUE-TERM:{}", tokenAtt.ref());
   328→								if (tokenAtt.ref().length() != extractor.getTabularSize()) {
   329→									extPosition -= tokenAtt.ref().length();
   330→									continueTerm = true;
   331→								}
   332→							}
   333→							extLength = position - extPosition;
   334→							if (extLength > extractor.getTabularSize()) {
   335→								extLength = extractor.getTabularSize();
   336→								tabularFull = true;
   337→							} else {
   338→								tabularFull = false;
   339→							}
   340→							logger.trace("EXTRACT:{} / {}~{} / {}", new CharVector(buffer, extPosition, extLength), extPosition, extLength, baseOffset);
   341→							extractor.setInput(buffer, extPosition, extLength);
   342→							entry = extractor.extract();
   343→							if (continueTerm) {
   344→								continue;
   345→							}
   346→						}
   347→					}
   348→					// 마지막 공백이 있는경우 건너뜀
   349→					for (; extPosition < tokenLength; extPosition++) {
   350→						if (getType(buffer[extPosition]) != WHITESPACE) { break;} 
   351→					}
   352→					if (extPosition == tokenLength) {
   353→						logger.trace("TOKENIZER BUFFER EXHAUSTED!");
   354→						tokenAtt.addState(TokenInfoAttribute.STATE_INPUT_BUFFER_EXHAUSTED);
   355→						continue;
   356→					}
   357→					break;
   358→				}
   359→				logger.trace("OFFSET:{} / {} / {} / {}", startOffset, endOffset, position, baseOffset + readLength);
   360→			}
   361→			return true;
   362→		}
   363→		return false;
   364→	}
   365→  
   366→	@Override
   367→	public final void end() throws IOException {
   368→		logger.trace("TOKENIZER-END {}", finalOffset);
   369→		super.end();
   370→		offsetAtt.setOffset(finalOffset, finalOffset);
   371→	}
   372→
   373→	@Override
   374→	public void reset() throws IOException {
   375→		logger.trace("TOKENIZER-RESET");
   376→		super.reset();
   377→		position = 0;
   378→		extLength = 0;
   379→		baseOffset = 0;
   380→		readLength = 0;
   381→		finalOffset = 0;
   382→		tokenLength = 0;
   383→		chrCurrent = 0;
   384→		typeCurrent = null;
   385→		tabularFull = false;
   386→	}
   387→
   388→	@Override
   389→	public void close() throws IOException {
   390→		logger.trace("TOKENIZER-CLOSE");
   391→		super.close();
   392→	}
   393→
   394→	public static boolean containsChar(char[] array, char c) {
   395→		// 문자소지여부확인
   396→		for (char ch : array) {
   397→			if (ch == c) {
   398→				return true;
   399→			}
   400→		}
   401→		return false;
   402→	}
   403→
   404→	public static boolean containsChar(char[] array, char[] buf, int length) {
   405→		// 여러개 문자중 하나라도 소지하고 있는지 확인
   406→		for (char ch : array) {
   407→			if (!containsChar(array, ch)) {
   408→				return false;
   409→			}
   410→		}
   411→		return true;
   412→	}
   413→
   414→
   415→	public static String isSplit(char c) {
   416→		String ret = getType(c);
   417→		if (ret == WHITESPACE || ret == SYMBOL) {
   418→			return ret;
   419→		} else if (ret == SYMBOL && (containsChar(AVAIL_SYMBOLS_SPLIT, c) || (c > 128))) {
   420→			// unicode 특수문자는 모두 구분자로 사용한다.
   421→			return ret;
   422→		}
   423→		return null;
   424→	}
   425→
   426→	public static String getUniType(CharSequence cv) {
   427→		String ret = null;
   428→		String prevType = null;
   429→		String type = null;
   430→		for (int inx = 0; inx < cv.length(); inx++) {
   431→			prevType = type;
   432→			type = getType(cv.charAt(inx));
   433→			if (prevType != null && type != prevType) {
   434→				if (prevType != type) {
   435→					type = UNCATEGORIZED;
   436→					break;
   437→				}
   438→			}
   439→		}
   440→		ret = type;
   441→		return ret;
   442→	}
   443→
   444→	public static boolean isAlphaNum(CharVector cv) {
   445→		boolean ret = true;
   446→		if (cv.length() == 0) {
   447→			return false;
   448→		}
   449→		for (int inx = 0; inx < cv.length(); inx++) {
   450→			String type = ProductNameTokenizer.getType(cv.array()[cv.offset() + inx]);
   451→			if (!(type == ProductNameTokenizer.ALPHA || type == ProductNameTokenizer.NUMBER)) {
   452→				ret = false;
   453→				break;
   454→			}
   455→		}
   456→		return ret;
   457→	}
   458→
   459→	public static String getTermType(CharSequence cv) {
   460→		String ret = null;
   461→		String prevType = null;
   462→		String type = null;
   463→		for (int inx = 0; inx < cv.length(); inx++) {
   464→			prevType = type;
   465→			type = getType(cv.charAt(inx));
   466→			// logger.trace("TYPE:{} / {}", type, cv);
   467→			if (prevType != null && type != prevType) {
   468→				if ((prevType == ALPHA && type == NUMBER) || (prevType == NUMBER && type == ALPHA)) {
   469→					type = ALPHANUM;
   470→				} else if (prevType == ALPHANUM && (type == ALPHA || type == NUMBER)) {
   471→					type = ALPHANUM;
   472→				} else if ((prevType == ALPHA && type == SYMBOL) || (prevType == NUMBER && type == SYMBOL)
   473→						|| (prevType == ALPHANUM && type == SYMBOL)) {
   474→					type = ASCII;
   475→				} else if (prevType == ASCII && (type == ALPHA || type == NUMBER || type == SYMBOL)) {
   476→					type = ASCII;
   477→				} else {
   478→					type = UNCATEGORIZED;
   479→				}
   480→			} else {
   481→
   482→			}
   483→			// logger.trace("TYPE:{} / PREV:{}", type, prevType);
   484→		}
   485→		ret = type;
   486→		return ret;
   487→	}
   488→
   489→	public static String getType(int ch) {
   490→		if(Character.isWhitespace(ch)){
   491→			return WHITESPACE;
   492→		}
   493→		
   494→		int type = Character.getType(ch);
   495→		
   496→		switch(type){
   497→		case Character.DASH_PUNCTUATION:
   498→		case Character.START_PUNCTUATION:
   499→		case Character.END_PUNCTUATION:
   500→		case Character.CONNECTOR_PUNCTUATION:
   501→		case Character.OTHER_PUNCTUATION:
   502→		case Character.MATH_SYMBOL:
   503→		case Character.CURRENCY_SYMBOL:
   504→		case Character.MODIFIER_SYMBOL:
   505→		case Character.OTHER_SYMBOL:
   506→		case Character.INITIAL_QUOTE_PUNCTUATION:
   507→		case Character.FINAL_QUOTE_PUNCTUATION:
   508→			return SYMBOL;
   509→		case Character.OTHER_LETTER:
   510→			//외국어.
   511→			Character.UnicodeBlock unicodeBlock = Character.UnicodeBlock.of(ch);
   512→			if (unicodeBlock == Character.UnicodeBlock.HANGUL_SYLLABLES){
   513→				return HANGUL;
   514→			} else if (unicodeBlock == Character.UnicodeBlock.HANGUL_COMPATIBILITY_JAMO) {
   515→				return HANGUL_JAMO;
   516→			} else if (unicodeBlock == Character.UnicodeBlock.HIRAGANA || unicodeBlock == Character.UnicodeBlock.KATAKANA) {
   517→				return JAPANESE;
   518→			} else if (unicodeBlock == Character.UnicodeBlock.CJK_UNIFIED_IDEOGRAPHS) {
   519→				return CHINESE;
   520→			}else{
   521→				return OTHER_LANGUAGE;
   522→			}
   523→		case Character.UPPERCASE_LETTER:
   524→		case Character.LOWERCASE_LETTER:
   525→			//영어.
   526→			return ALPHA;
   527→			
   528→		case Character.DECIMAL_DIGIT_NUMBER:
   529→			return NUMBER;
   530→		}
   531→		
   532→		return UNCATEGORIZED;
   533→	}
   534→}

