   277→	private int connectAllTo(int headRow, ExtractedEntry tail) throws AnalyzeExceedException {
   278→		PosTagProbEntry[] rowData = tabular[headRow];
   279→		int found = 0;
   280→		// 최장길이부터 찾는다.
   281→		for (int headColumn = headRow + 1; headColumn > 0; headColumn--) {
   282→			if (rowData[headColumn] != null) {
   283→				PosTagProbEntry tagEntry = rowData[headColumn];
   284→				entryStringer.set(tagEntry, source, headRow, headColumn, offset);
   285→				/* 2019.3.28 @swsong 알파벳은 무조건 성공분석으로 잡혀서 사전에 없는 단어들도 후보가 되어 ALPHA를 건너뛰게 한다. */
   286→				if (tagEntry.tagProb.posTag() != PosTag.ALPHA) {
   287→					connectTo(tagEntry, headRow, headColumn, tail);
   288→					found++;
   289→				}
   290→			}
   291→
   292→			// 갯수만큼 다 찾았으면 일찍 종료한다.
   293→			if (found >= status[headRow]) {
   294→				break;
   295→			}
   296→
   297→		}
   298→		// 추가 20190725 (영문인경우 모두 분석되어야 분석성공으로 만들도록)
   299→		// logger.trace("CHECK:{} / {}", isUnicode, result);
   300→		if (!isUnicode) {
   301→			for (int inx = 0; inx < result.size(); inx++) {
   302→				if (result.get(inx).last().posTag() == PosTag.UNK) {
   303→					result.remove(inx);
   304→					inx--;
   305→				}
   306→			}
   307→		}
   308→		return found;
   309→	}
