   311→	private int connectTo(PosTagProbEntry headTagEntry, int headRow, int headColumn, ExtractedEntry tail) throws AnalyzeExceedException {
   312→		// entryStringer.set(headTagEntry, source, headRow, headColumn, offset);
   313→		// logger.trace("CONNECTTO:{}/{}", entryStringer, tail);
   314→		// headColumn = -1 이면 앞쪽에 연결될 단어가 없는것이다.
   315→		if (tail == null) {
   316→			// 처음
   317→			int found = 0;
   318→			while (headTagEntry != null) {
   319→				ExtractedEntry headEntry = new ExtractedEntry(headRow, headColumn, headTagEntry.get(), offset);
   320→				if (headEntry.row() - headEntry.column() < 0) {
   321→					addResult(headEntry);
   322→				} else {
   323→					addQueue(headEntry);
   324→				}
   325→				headTagEntry = headTagEntry.next;
   326→				found++;
   327→			}
   328→			// 바로리턴.
   329→			return found;
   330→		}
   331→
   332→		if (headTagEntry == null) {
   333→			// 해당 row의 모든 column을 확인해본다.
   334→			for (int column = 1; column <= headRow + 1; column++) {
   335→				int row2 = headRow - column;
   336→				// head앞에 결합가능한 것이 있다면 현재 head를 미등록처 처리하고 링크로 이어준다.
   337→				// 앞쪽에 결합가능한것이 없으면 현재 head는 버린다.
   338→				// row2 < 0 는 어절의 처음에 도달한것임.
   339→				if (row2 < 0 || status[row2] > 0) {
   340→					// 2014-1-27처리..
   341→				}
   342→			}
   343→			return 1;
   344→		}
   345→		
   346→		int found = 0;
   347→		while (headTagEntry != null) {
   348→			if (isConnectableByRule(headTagEntry.get(), headRow, headColumn, tail)) {
   349→				ExtractedEntry newTail = modifyAndConnect(headTagEntry.get(), headRow, headColumn, tail);
   350→				if (newTail == null) {
   351→					// null이면 버리는것이므로 다음으로..
   352→				} else {
   353→					if (newTail.row() - newTail.column() < 0) {
   354→						addResult(newTail);
   355→					} else {
   356→						addQueue(newTail);
   357→					}
   358→					found++;
   359→				}
   360→			}
   361→			headTagEntry = headTagEntry.next;
   362→		}
   363→		return found;
   364→	}
