   366→	protected void addQueue(ExtractedEntry entry) throws AnalyzeExceedException {
   367→		if (fastResultFound) {
   368→			return;
   369→		}
   370→		// 결과로 넣음.
   371→		// logger.trace("ADD-QUEUE:{}", entry);
   372→		queue.add(entry);
   373→		if (queue.size() >= QUEUE_MAX) {
   374→			throw new AnalyzeExceedException("Queue size exceed " + queue.size() + " : " + new String(source));
   375→		}
