   378→	protected void addResult(ExtractedEntry entry) throws AnalyzeExceedException {
   379→		// logger.trace("ADD-RESULT:{}", entry);
   380→		ExtractedEntry e = finalCheck(entry);
   381→		if (e == null) {
   382→			return;
   383→		}
   384→		// 결과로 넣음.
   385→		result.add(entry);
   386→
   387→		// 짧은 문장에서는 사용하지 않음.
   388→		if (fastResultOption && length > 6) {
   389→			fastResultFound = true;
   390→			queue.clear();
   391→		}
   392→
   393→		if (result.size() >= RESULT_MAX) {
   394→			ExtractedEntry tmpResult = getHighResult();
   395→			result.clear();
   396→			if (tmpResult != null) {
   397→				result.add(tmpResult);
   398→			}
   399→		}
   400→	}
