   406→	public int setInput(char[] buffer, int offset, int length) {
   407→		remnantOffset = 0;
   408→		remnantLength = 0;
   409→		isUnicode = isUnicode(buffer, offset, length);
   410→		Arrays.fill(status, 0);
   411→		for (int row = 0; row < tabular.length; row++) {
   412→			for (int col = 0; col < tabular[row].length; col++) {
   413→				tabular[row][col] = null;
   414→			}
   415→		}
   416→		result.clear();
   417→		
   418→		String type = null;
   419→		String ptype = null;
   420→		String pptype = null;
   421→		if (length > tabular.length) {
   422→			logger.trace("LENGTH IS OVER THAN {} / {} / {}", length, tabular.length, offset);
   423→			// 내부적으로 자를 수 있는 기준을 살펴 본다.
   424→			// 자를수 있는 기준은 다음과 같다.
   425→			// 한글 사이의 특수 문자. ( & 제외 : 존슨&존스 등 )
   426→			for (int inx = offset + length; inx > offset; inx--) {
   427→				pptype = ptype;
   428→				ptype = type;
   429→				type = getType(buffer[inx - 1]);
   430→				if (logger.isTraceEnabled()) {
   431→					logger.trace("PP:{}/P:{}/T:{}/C:{} {} [{}/{}/{} | {}/{}/{}]", pptype, ptype, type, buffer[inx - 1],
   432→						inx - offset,
   433→						(pptype != null && (pptype != ALPHA && pptype != NUMBER)),
   434→						(inx < buffer.length && ptype == SYMBOL && buffer[inx] != '&'),
   435→						(type != null), (pptype != null),
   436→						(inx < buffer.length && ptype == SYMBOL && buffer[inx] != '&'),
   437→						(type != null && (type != ALPHA && type != NUMBER)));
   438→				}
   439→				if (((pptype != null && (pptype != ALPHA && pptype != NUMBER))
   440→						&& (inx < buffer.length && ptype == SYMBOL && buffer[inx] != '&')
   441→						&& (type != null))
   442→						|| ((pptype != null) && (inx < buffer.length && ptype == SYMBOL && buffer[inx] != '&')
   443→							&& (type != null && (type != ALPHA && type != NUMBER)))) {
   444→					logger.trace("LENGTH:{} / {}", length - offset, tabular.length);
   445→					length = inx - offset;
   446→					if (length <= tabular.length) {
   447→						logger.trace("BREAK INTO {}", length);
   448→						break;
   449→					}
   450→				}
   451→			}
   452→			//여기까지 와서 찾지 못했다면, 앞에서부터 최초 타입이 달라지는 순간 끊어준다.
   453→			//영숫자+기호 : 한글
   454→			if (length > tabular.length) {
   455→				type = null;
   456→				for (int inx = offset; inx < (offset + length); inx++) {
   457→					ptype = type;
   458→					type = getType(buffer[inx]);
   459→					if (ptype != null && (
   460→						( (type == ALPHA || type == NUMBER || type == SYMBOL)
   461→							&& !(ptype == ALPHA || ptype == NUMBER || ptype == SYMBOL) )
   462→						|| (!(type == ALPHA || type == NUMBER || type == SYMBOL)
   463→							&& (ptype == ALPHA || ptype == NUMBER || ptype == SYMBOL)) )) {
   464→						length = inx - offset;
   465→					}
   466→				}
   467→			}
   468→			
   469→			if (length > tabular.length) {
   470→				if (logger.isTraceEnabled()) {
   471→					logger.trace("CUT TABULAR SIZE : {}/ {} -> {}", length, new String(buffer, offset, length), new String(buffer, offset, tabular.length));
   472→				}
   473→				remnantOffset = tabular.length;
   474→				remnantLength = length - tabular.length;
   475→				length = tabular.length;
   476→			}
   477→		}
   478→		length = setInput0(buffer, offset, length);
   479→		return length;
   480→	}
