   494→	public ExtractedEntry extract() {
   495→		tabularStringer.set(tabular, source, status, length, offset);
   496→		ExtractedEntry.source = source;
   497→		ExtractedEntry e = extract0();
   498→		ExtractedEntry last = e.last();
   499→		while (remnantLength > 0) {
   500→			int len = Math.min(tabular.length, remnantLength);
   501→			// 자른다.
   502→			setInput0(source, remnantOffset, len);
   503→			ExtractedEntry r = extract0();
   504→			if (r != null) {
   505→				// 잘못된 데이터. 순서적으로 나올수 없는 조합.
   506→				if (!(last.offset() + last.column() > r.offset())) {
   507→					last.next(r);
   508→					last = r.last();
   509→				}
   510→			}
   511→			remnantOffset += len;
   512→			remnantLength -= len;
   513→		}
   514→		return e;
   515→	}
