   569→	/*
   570→	 * 두 PosTag간의 룰기반 접속문법검사
   571→	 */
   572→	protected boolean isConnectableByRule(TagProb headTagProb, int headRow, int headColumn, ExtractedEntry tail) {
   573→		//숫자끼리는 과분석된것이므로 연결해주지 않는다. 제일 긴 숫자가 사용하도록함.
   574→		if (headTagProb.posTag() == PosTag.DIGIT && tail.tagProb().posTag() == PosTag.DIGIT) {
   575→			return false;
   576→		}
   577→		if (headTagProb.posTag() == PosTag.ALPHA && tail.tagProb().posTag() == PosTag.ALPHA) {
   578→			return false;
   579→		}
   580→		if (headTagProb.posTag() == PosTag.SYMBOL && tail.tagProb().posTag() == PosTag.SYMBOL) {
   581→			return false;
   582→		}
   583→		if (headTagProb.posTag() != PosTag.ALPHA && headTagProb.posTag() != PosTag.DIGIT && headTagProb.posTag() != PosTag.SYMBOL) {
   584→			// //은,이 와 는,가 일때 앞의 단어에 받침이 있는 지 확인.
   585→			if (tail.tagProb().posTag() == PosTag.J && tail.column() == 1) {
   586→				// "은 는 이 가 을 를 에 과 와 의 께";
   587→				char ch = source[offset + tail.row() - tail.column() + 1];
   588→				if (ch == '은' || ch == '이' || ch == '을' || ch == '과') {
   589→					if (!MorphUtil.hasLastElement(source[offset + headRow])) {
   590→						return false;
   591→					}
   592→				} else if (ch == '는' || ch == '가' || ch == '를' || ch == '와') {
   593→					if (MorphUtil.hasLastElement(source[offset + headRow])) {
   594→						return false;
   595→					}
   596→				}
   597→			}
   598→		}
   599→
   600→		// 두개 모두 한글자분석이면서 점수가 -12이하인것이 하나라도 있으면 통짜로 미등록어처리.
   601→		if (headColumn == 1 && tail.column() == 1 && headTagProb.posTag() != PosTag.J && tail.posTag() != PosTag.J) {
   602→			if (tabular[tail.row()][tail.column() + headColumn] != null) {
   603→				// 단어가 존재하므로 버린다.
   604→				return false;
   605→			}
   606→		}
   607→		//3개연속 불허용.
   608→		return true;
   609→	}
