   611→	/*
   612→	 * 두 엔트리를 접속시 합치거나 이어붙이는 로직을 구현한다.
   613→	 */
   614→	protected ExtractedEntry modifyAndConnect(TagProb tagProb, int row, int column, ExtractedEntry tail) {
   615→		ExtractedEntry newEntry = new ExtractedEntry(row, column, tagProb, offset);
   616→		return newEntry.next(tail);
   617→	}
