   619→	private ExtractedEntry finalCheck(ExtractedEntry headEntry) {
   620→		// 첫글자 조사버림.
   621→		if (headEntry.posTag() == PosTag.J) {
   622→			return null;
   623→		}
   624→
   625→		int count = 0;
   626→		if (headEntry.entryCount() >= 2) {
   627→			ExtractedEntry current = headEntry;
   628→			while (current != null) {
   629→				if (current.column() > 1) {
   630→					break;
   631→				} else {
   632→					count++;
   633→				}
   634→				current = current.next();
   635→			}
   636→		}
   637→
   638→		if (count == headEntry.entryCount()) {
   639→			if (headEntry.last().posTag() == PosTag.J) {
   640→				return headEntry;
   641→			}
   642→			return null;
   643→		}
   644→		/*
   645→		 * 한글자 + GUESS(or -15미만) 결합은 합친다.
   646→		 */
   647→		return headEntry;
   648→	}
