   650→	/*
   651→	 * Best 결과를 뽑을때 사용하는 비교로직.
   652→	 */
   653→	protected boolean isBetterThan(ExtractedEntry entry, ExtractedEntry bestEntry) {
   654→		// 적게 잘린쪽이 우선.
   655→		// 2014-1-27 처리.. 이렇게 하면 무조건 항상 통 UNK가 나오게 된다.
   656→
   657→		// 점수가 큰쪽이 우선.
   658→		if (entry.totalScore() > bestEntry.totalScore()) {
   659→			return true;
   660→		}
   661→		return false;
   662→	}
