    85→	private static File getDictionaryFile(File envBase, JSONObject prop, String basePath) {
    86→		File ret = null;
    87→		// 속성에서 발견되면 속성내부 경로를 사용해 파일을 얻어오며, 그렇지 않은경우 지정된 경로에서 사전파일을 얻어온다
    88→		File baseFile = null;
    89→		try {
    90→			// 베이스파일이 속성에 있으면 먼저 시도.
    91→			if (basePath != null && !"".equals(basePath)) {
    92→				baseFile = new File(basePath);
    93→			}
    94→			if (baseFile == null || !baseFile.exists()) { baseFile = envBase; }
    95→		} catch (Exception e) { 
    96→			logger.debug("DICTIONARY EXCEPTION : {} / {}", baseFile, e.getMessage());
    97→			baseFile = envBase;
    98→		}
    99→		String dictionaryId = prop.optString(ATTR_DICTIONARY_NAME, "").trim();
   100→		String path = prop.optString(ATTR_DICTIONARY_FILE_PATH, "").trim();
   101→		ret = new File(baseFile, path);
   102→		if (path == null || !ret.exists()) {
   103→			ret = new File(new File(envBase, dictionaryPath), dictionaryId + dictionarySuffix);
   104→		}
   105→		return ret;
   106→	}
