   161→		for (int tries = 0; tries < 2; tries++) {
   162→			try {
   163→				if (tries == 0) {
   164→					baseFile = ResourceResolver.getResourceRoot(ProductNameDictionary.class);
   165→				} else {
   166→					// 설정파일이 플러그인 디렉토리에 존재하지 않는다면 검색엔진 conf 디렉토리에서 설정파일을 찾는다.
   167→					// 추후 불필요시 삭제한다. (설정파일 혼란이 있을수 있음)
   168→					baseFile = env.configDir().toFile();
   169→				}
   170→				logger.debug("TESTING PRODUCT DICTIONARY BASE : {}", baseFile.getAbsolutePath());
   171→				if (baseFile != null && baseFile.exists()) {
   172→					logger.debug("PRODUCT DICTIONARY BASE : {}", baseFile.getAbsolutePath());
   173→				}
   174→			} catch (Exception e) {
   175→				logger.error("", e);
   176→				baseFile = null;
   177→				configFile = null;
   178→				continue;
   179→			}
   180→			configFile = new File(baseFile, ANALYSIS_PROP);
   181→			if (configFile.exists()) {
   182→				logger.debug("DICTIONARY PROPERTIES : {}", configFile.getAbsolutePath());
   183→				break;
   184→			} else {
   185→				baseFile = null;
   186→				configFile = null;
