    14→
    15→public class Entry {
    16→    private static final Logger logger = LogManager.getLogger(Entry.class);
    17→
    18→    int start;
    19→    int lastPosition;
    20→
    21→    public static Entry init(List<RuleEntry> queue) {
    22→        Entry e = new Entry();
    23→        if (queue.size() > 0) {
    24→            e.start = queue.get(0).start;
    25→            RuleEntry lastOne = queue.get(queue.size() - 1);
    26→            e.lastPosition = lastOne.start + lastOne.length;
    27→        }
    28→        return e;
    29→    }
    30→
    31→    // e1을 e0에 붙여서 하나의 텀으로 만든다.
    32→    public static void merge(RuleEntry e0, RuleEntry e1, String type) {
    33→        e0.length = (e1.start + e1.length - e0.start);
    34→        e0.endOffset = e1.endOffset;
    35→        e0.type = type;
    36→    }
    37→
    38→    public static boolean isConnected(RuleEntry prevEntry, RuleEntry entry) {
    39→        return entry.start == prevEntry.start + prevEntry.length;
    40→    }
    41→
    42→    // e1을 e0에 붙여서 새로운 텀을 만든다.
    43→    public static RuleEntry mergeNewEntry(RuleEntry e0, RuleEntry e1, String type) {
    44→        RuleEntry e3 = e0.clone();
    45→        e3.length = (e1.start + e1.length - e0.start);
    46→        e3.endOffset = e1.endOffset;
    47→        e3.type = type;
    48→        return e3;
    49→    }
    50→
    51→    // e1, e2을 e0에 붙여서 새로운 텀을 만든다.
    52→    public static RuleEntry mergeNewEntry(RuleEntry e0, RuleEntry e1, RuleEntry e2, String type) {
    53→        RuleEntry e3 = mergeNewEntry(e0, e1, type);
    54→        e3.length = (e2.start + e2.length - e3.start);
    55→        e3.endOffset = e2.endOffset;
    56→        e3.type = type;
    57→        return e3;
    58→    }
    59→
    60→    public static void addEntry(List<RuleEntry> termList, CharVector ref, String type, PosTagProbEntry.PosTag posTag, int startOffset, int endOffset, SpaceDictionary spaceDictionary) {
    61→        if (type == FULL_STRING) {
    62→            // NOP
    63→        } else if (posTag == PosTagProbEntry.PosTag.N) {
    64→            type = HANGUL;
    65→        } else if (posTag == PosTagProbEntry.PosTag.DIGIT) {
    66→            type = NUMBER;
    67→        } else if (posTag == PosTagProbEntry.PosTag.ALPHA) {
    68→            type = ALPHA;
    69→        } else if (posTag == PosTagProbEntry.PosTag.SYMBOL) {
    70→            type = SYMBOL;
    71→        } else if (posTag == null || posTag == PosTagProbEntry.PosTag.UNK) {
    72→            type = UNCATEGORIZED;
    73→        }
    74→        if (type != FULL_STRING && spaceDictionary != null && spaceDictionary.containsKey(ref)) {
    75→            // 분리어가 발견되면
    76→            int offsetSt = startOffset;
    77→            CharSequence[] splits = spaceDictionary.get(ref);
    78→            logger.trace("SPLIT:{}{}", "", splits);
    79→            for (int sinx = 0, position = 0; sinx < splits.length; sinx++) {
    80→                int length = splits[sinx].length();
    81→                if (sinx > 0) {
    82→                    // 강제 분리를 위한 빈공백
    83→                    termList.add(new RuleEntry(ref.array(), position, 0,
    84→                            offsetSt + position, offsetSt + position, SYMBOL));
    85→                }
    86→                termList.add(new RuleEntry(ref.array(), ref.offset() + position, length,
    87→                        offsetSt + position, offsetSt + position + length, HANGUL));
    88→                position += length;
    89→            }
    90→        } else {
    91→            termList.add(new RuleEntry(ref.array(), ref.offset(), ref.length(),
    92→                    startOffset, endOffset, type));
