   387→    public static void mergeSubQueue(RuleEntry entry, List<RuleEntry> subQueue, AnalyzerOption option, SetDictionary unitDictionary) {
   388→        if (entry.type == MODEL_NAME) {
   389→            // 바이트 비교가 많으므로 버퍼기준으로 처리하도록 한다.
   390→            boolean processed = false;
   391→            if (subQueue.size() == 3) {
   392→                // 모델명이 3블럭이며, 가운데 기호가 있는 경우, 붙여서만 출력함.
   393→                // 단위명 + 1글자 등의 조합으로 나올수 있으므로 일단 합쳐서 체크하도록 한다.
   394→                int contCnt = 0;
   395→                RuleEntry initEntry = subQueue.get(0).clone();
   396→                RuleEntry prevEntry = initEntry;
   397→                for (int cinx = 1; cinx < subQueue.size(); cinx++, contCnt++) {
   398→                    RuleEntry currentEntry = subQueue.get(cinx);
   399→                    if (prevEntry.startOffset + prevEntry.length != currentEntry.startOffset) {
   400→                        break;
   401→                    }
   402→                    initEntry.length += currentEntry.length;
   403→                    prevEntry = currentEntry;
   404→                }
   405→                // 합칠수 있는 블럭인 경우.
   406→                if (contCnt > 0 && contCnt == subQueue.size() - 1) {
   407→                    if (initEntry.length == 2) {
   408→                        String charType = getType(initEntry.buf[initEntry.start]);
   409→                        String nextCharType = getType(initEntry.buf[initEntry.start + 1]);
   410→                        if ((charType == ALPHA || charType == NUMBER) &&
   411→                                // 모델명이 2블럭이며, 영숫자 + 특수기호 인 경우
   412→                                (nextCharType == SYMBOL)) {
   413→                            entry.length -= 1;
   414→                            entry.endOffset -= 1;
   415→                            entry.type = charType;
   416→                            subQueue.clear();
   417→                            processed = true;
   418→                        } else if ((charType == SYMBOL) &&
   419→                                // 모델명이 2블럭이며, 영숫자 + 특수기호 인 경우
   420→                                (nextCharType == ALPHA || nextCharType == NUMBER)) {
   421→                            entry.start++;
   422→                            entry.startOffset++;
   423→                            entry.length--;
   424→                            entry.type = nextCharType;
   425→                            subQueue.clear();
   426→                            processed = true;
   427→                        } else if (charType != nextCharType &&
   428→                                // 모델명이 2블럭이며, 1글자씩이 붙어서 나온 것이면 붙여서만 출력 한다.
   429→                                (charType == ALPHA || charType == NUMBER) &&
   430→                                (nextCharType == ALPHA || nextCharType == NUMBER)) {
   431→                            subQueue.clear();
   432→                            processed = true;
   433→                        }
   434→                    } else if (initEntry.length == 3) {
   435→                        String charType = getType(initEntry.buf[initEntry.start]);
   436→                        String nextCharType = getType(initEntry.buf[initEntry.start + 1]);
   437→                        String nextNextCharType = getType(initEntry.buf[initEntry.start + 2]);
   438→                        if ((charType == ALPHA || charType == NUMBER) &&
   439→                                (nextCharType == SYMBOL) &&
   440→                                (nextNextCharType == ALPHA || nextNextCharType == NUMBER)) {
   441→                            subQueue.clear();
   442→                        } else if (charType != nextCharType && nextCharType != nextNextCharType &&
   443→                                (charType == ALPHA || charType == NUMBER) &&
   444→                                (nextCharType == ALPHA || nextCharType == NUMBER) &&
   445→                                (nextNextCharType == ALPHA || nextNextCharType == NUMBER)) {
   446→                            subQueue.clear();
   447→                        }
   448→                        processed = true;
   449→                    }
   450→                }
   451→            }
   452→            if (!processed) {
   453→                if (subQueue.size() == 2) {
   454→                    // 모델명이 2블럭이며, 1글자씩이 붙어서 나온 것이면 붙여서만 출력 한다.
   455→                    RuleEntry currentEntry = subQueue.get(0);
   456→                    RuleEntry nextEntry = subQueue.get(1);
   457→                    if (currentEntry.length == 1 && nextEntry.length == 1) {
   458→                        subQueue.clear();
   459→                    } else if (currentEntry.type == SYMBOL) {
   460→                        entry.start += currentEntry.length;
   461→                        entry.startOffset += currentEntry.length;
   462→                        entry.length -= currentEntry.length;
   463→                        entry.type = nextEntry.type;
   464→                    } else if (nextEntry.type == SYMBOL) {
   465→                        entry.length -= nextEntry.length;
   466→                        entry.endOffset -= nextEntry.length;
   467→                        entry.type = currentEntry.type;
   468→                    }
   469→                } else if (subQueue.size() == 3) {
   470→                    RuleEntry currentEntry = subQueue.get(0);
   471→                    RuleEntry nextEntry = subQueue.get(1);
   472→                    RuleEntry nextNextEntry = subQueue.get(2);
   473→                    if (currentEntry.length == 1 && nextEntry.length == 1 && nextNextEntry.length == 1) {
   474→                        // 모델명이 3블럭이며, 가운데 기호가 있는 경우, 붙여서만 출력함.
   475→                        if ((currentEntry.type == ALPHA || currentEntry.type == NUMBER)
   476→                                && (nextNextEntry.type == ALPHA || nextNextEntry.type == NUMBER)) {
   477→                            if (nextEntry.type == SYMBOL) {
   478→                                if (nextEntry.buf[nextEntry.start] != '+') {
   479→                                    subQueue.clear();
   480→                                }
   481→                            } else if (currentEntry.type == nextNextEntry.type) {
   482→                                currentEntry.length += nextEntry.length + nextNextEntry.length;
   483→                                currentEntry.endOffset = nextNextEntry.endOffset;
   484→                                subQueue.remove(2);
   485→                                subQueue.remove(1);
   486→                            }
   487→                        }
   488→                    }
   489→                }
   490→            }
   491→
   492→            int continuous = 0;
   493→
   494→            logger.trace("subQueue : {}", subQueue);
   495→
   496→            // 2014.08.29 1byte 씩 영문자 숫자가 교차되어 발견되는 구간에서 '-' 등의 특수기호로 연결 되어 있다면
   497→            // 교차된 영 숫자는 분리하지 않는다.
   498→            for (int inx = 0; inx <= subQueue.size(); inx++) {
   499→                RuleEntry workingEntry = null;
   500→                if (inx < subQueue.size()) {
   501→                    workingEntry = subQueue.get(inx);
   502→                }
   503→                // 1바이트씩 교차되어 나타나는 영문, 숫자들 1a2b3c....
   504→                if (workingEntry != null && workingEntry.length == 1 && (workingEntry.type == ALPHA || workingEntry.type == NUMBER)) {
   505→                    logger.trace("e0:{} / {}:{}", workingEntry, inx, continuous);
   506→                    continuous++;
   507→                } else if (continuous > 1) {
   508→
   509→                    boolean frontMatch = inx > 0 && (inx - continuous) > 0;
   510→                    if (frontMatch) {
   511→                        RuleEntry prevEntry = subQueue.get(inx - continuous - 1);
   512→                        if (!(prevEntry.type == SYMBOL && prevEntry.length == 1)) {
   513→                            frontMatch = false;
   514→                        }
   515→                    }
   516→
   517→                    boolean rearMatch = inx > 0 && inx < subQueue.size();
   518→
   519→                    if (rearMatch) {
   520→                        RuleEntry nextEntry = subQueue.get(inx);
   521→                        if (!(nextEntry.type == SYMBOL && nextEntry.length == 1)) {
   522→                            rearMatch = false;
   523→                        }
   524→                    }
   525→
   526→                    if (inx < subQueue.size()) {
   527→                        logger.trace("inx:{}/{} / continuous:{} / fmatch:{} / rmatch:{} / entry:{}", inx, subQueue.size(), continuous, frontMatch, rearMatch, subQueue.get(inx));
   528→                    }
   529→
   530→                    //
   531→                    // 2016.05.13 추가규칙.
   532→                    // 다음과 같은 규칙으로 변경
   533→                    /**
   534→                     * 1b-12345	(1b 1 b 12345 1b-12345) -> I/Q(1b 12345 1b-12345)
   535→                     * b1/a2s	(b1 b 1 a 2 s a2s b1/a2s) -> I/Q(b1 a 2 s a2s b1/a2s)
   536→                     * c9-123567	(c9 c 9 123567 9123567 c9-123567) -> I(c9 123567 9123567 c9-123567)/Q(c9 123567 c9-123567)
