package com.danawa.search.analysis.product.rule;

import com.danawa.search.analysis.dict.SetDictionary;
import com.danawa.search.analysis.dict.SpaceDictionary;
import com.danawa.search.analysis.korean.PosTagProbEntry;
import com.danawa.search.analysis.product.AnalyzerOption;
import com.danawa.util.CharVector;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import java.util.*;

import static com.danawa.search.analysis.product.ProductNameTokenizer.*;

public class Entry {
    private static final Logger logger = LogManager.getLogger(Entry.class);

    int start;
    int lastPosition;

    public static Entry init(List<RuleEntry> queue) {
        Entry e = new Entry();
        if (queue.size() > 0) {
            e.start = queue.get(0).start;
            RuleEntry lastOne = queue.get(queue.size() - 1);
            e.lastPosition = lastOne.start + lastOne.length;
        }
        return e;
    }

    // e1을 e0에 붙여서 하나의 텀으로 만든다.
    public static void merge(RuleEntry e0, RuleEntry e1, String type) {
        e0.length = (e1.start + e1.length - e0.start);
        e0.endOffset = e1.endOffset;
        e0.type = type;
    }

    public static boolean isConnected(RuleEntry prevEntry, RuleEntry entry) {
        return entry.start == prevEntry.start + prevEntry.length;
    }

    // e1을 e0에 붙여서 새로운 텀을 만든다.
    public static RuleEntry mergeNewEntry(RuleEntry e0, RuleEntry e1, String type) {
        RuleEntry e3 = e0.clone();
        e3.length = (e1.start + e1.length - e0.start);
        e3.endOffset = e1.endOffset;
        e3.type = type;
        return e3;
    }

    // e1, e2을 e0에 붙여서 새로운 텀을 만든다.
    public static RuleEntry mergeNewEntry(RuleEntry e0, RuleEntry e1, RuleEntry e2, String type) {
        RuleEntry e3 = mergeNewEntry(e0, e1, type);
        e3.length = (e2.start + e2.length - e3.start);
        e3.endOffset = e2.endOffset;
        e3.type = type;
        return e3;
    }

    public static void addEntry(List<RuleEntry> termList, CharVector ref, String type, PosTagProbEntry.PosTag posTag, int startOffset, int endOffset, SpaceDictionary spaceDictionary) {
        if (type == FULL_STRING) {
            // NOP
        } else if (posTag == PosTagProbEntry.PosTag.N) {
            type = HANGUL;
        } else if (posTag == PosTagProbEntry.PosTag.DIGIT) {
            type = NUMBER;
        } else if (posTag == PosTagProbEntry.PosTag.ALPHA) {
            type = ALPHA;
        } else if (posTag == PosTagProbEntry.PosTag.SYMBOL) {
            type = SYMBOL;
        } else if (posTag == null || posTag == PosTagProbEntry.PosTag.UNK) {
            type = UNCATEGORIZED;
        }
        if (type != FULL_STRING && spaceDictionary != null && spaceDictionary.containsKey(ref)) {
            // 분리어가 발견되면
            int offsetSt = startOffset;
            CharSequence[] splits = spaceDictionary.get(ref);
            logger.trace("SPLIT:{}{}", "", splits);
            for (int sinx = 0, position = 0; sinx < splits.length; sinx++) {
                int length = splits[sinx].length();
                if (sinx > 0) {
                    // 강제 분리를 위한 빈공백
                    termList.add(new RuleEntry(ref.array(), position, 0,
                            offsetSt + position, offsetSt + position, SYMBOL));
                }
                termList.add(new RuleEntry(ref.array(), ref.offset() + position, length,
                        offsetSt + position, offsetSt + position + length, HANGUL));
                position += length;
            }
        } else {
            termList.add(new RuleEntry(ref.array(), ref.offset(), ref.length(),
                    startOffset, endOffset, type));
        }
    }

    public static int split(RuleEntry entry, List<RuleEntry> queue, int baseInx) {
        // if (entry.length < 2) { return 0; }
        logger.trace("split entry ({}) : {}~{}", entry, entry.start, entry.length);
        String ptype = null;
        String ctype = null;
        int st = 0;
        int addInx = 0;
        int offsetStarts = entry.startOffset;
        for (int inx = 0; inx < entry.length; inx++) {
            char ch = entry.buf[entry.start + inx];
            ctype = getType(ch);
            if (ptype != null && ptype != ctype) {
                RuleEntry entryClone = entry.clone();
                entryClone.start = entry.start + st;
                entryClone.length = inx - st;
                entryClone.type = ptype;

                entryClone.startOffset = offsetStarts + st;
                entryClone.endOffset = offsetStarts + st + entryClone.length;
                entryClone.modifiable = true;
                logger.trace("add splited entry : ({}) : {}~{}", entryClone, entryClone.start, entryClone.length);
                if (entryClone.type != WHITESPACE) {
                    queue.add(baseInx + addInx, entryClone);
                    addInx++;
                }
                // 엔트리 클로닝시 서브엔트리가 복제되는 버그 수정
                if (inx > 0) {
                    entryClone.subEntry = new ArrayList<>();
                    entryClone.synonym = null;
                }
                st = inx;
            }
            ptype = ctype;
        }
        if (addInx >= 0 && st < entry.length) {
            RuleEntry entryClone = entry.clone();
            if (ptype == null) {
                ptype = ctype;
            }
            entryClone.start = entry.start + st;
            entryClone.length = entry.length - st;
            entryClone.startOffset = offsetStarts + st;
            entryClone.endOffset = offsetStarts + st + entryClone.length;
            entryClone.type = ptype;
            entryClone.subEntry = new ArrayList<>();
            entryClone.synonym = null;
            logger.trace("add splited entry : ({}) : {}~{}", entryClone, entryClone.start, entryClone.length);
            queue.add(baseInx + addInx, entryClone);
            addInx++;
        }
        return addInx;
    }

    protected static RuleEntry mergeQueueIndex(int qinx, int typeContinuous, List<RuleEntry> queue, List<RuleEntry> subQueue) {
        int removeInx = qinx - typeContinuous;
        if (removeInx < 0) {
            removeInx = 0;
            typeContinuous--;
        }

        if (queue.get(removeInx + typeContinuous - 1).type == SYMBOL) {
            typeContinuous--;
        }

        if (typeContinuous == 1) {
            logger.trace("queue has only one entry. so don't merge it");
            return null;
        }

        logger.trace("queue[{}]={}", removeInx + typeContinuous - 1, queue.get(removeInx + typeContinuous - 1));

        RuleEntry entry = queue.get(removeInx).clone();
        logger.trace("ENTRY-CLONE:{}", entry);
        // 클로닝 되기 때문에 동의어를 반드시 삭제 해 주어야 한다.
        if (entry.type == UNIT_ALPHA) {
            entry.synonym = null;
        }
        entry.length = 0;
        entry.endOffset = entry.startOffset;
        String type = entry.type;
        RuleEntry subEntry;
        RuleEntry nextEntry = null;
        RuleEntry dummy = null;
        for (; typeContinuous > 0; typeContinuous--) {
            subEntry = queue.remove(removeInx);
            logger.trace("pop entry:{}/{}:{}[{}~{}] / {}", subEntry, subEntry.start, subEntry.length, subEntry.startOffset, subEntry.endOffset, subEntry.synonym);
            if (type != subEntry.type || (type == UNIT_ALPHA && subEntry.type == UNIT_ALPHA)) {
                type = null;
            }
            int start = subEntry.start;
            int length = subEntry.length;
            int endOffset = subEntry.endOffset;
            if (subQueue != null) {
                if (subEntry.type == UNIT_ALPHA) {
                    // 단위명이었지만 규칙에 의해 모델명으로 전환되는 경우.
                    // 단위명과 숫자를 구분해준다.
                    logger.trace("subList:{}{}", "", subEntry.subEntry);
                    if (subEntry.subEntry.size() > 0) {
                        int numIdx = 0;
                        // 숫자 인덱스 검출
                        for (RuleEntry e : subEntry.subEntry) {
                            if (e.type == NUMBER || e.type == NUMBER_TRANS) {
                                break;
                            } else if (numIdx == subEntry.subEntry.size() - 1) {
                                numIdx = 0;
                            }
                            numIdx++;
                        }
                        RuleEntry number = subEntry.subEntry.remove(numIdx);
                        subQueue.add(number);
                        subEntry.start += number.length;
                        subEntry.length -= number.length;
                        subEntry.startOffset += number.length;
                        subEntry.type = ALPHA;
                        // 단위명 뒤 엔트리가 영문이라면 단위명과 합치도록 한다. (118X71WXU3 -> 71W + XU -> 71 + WXU)
                        if (removeInx < queue.size() &&
                                (nextEntry = queue.get(removeInx)).type == ALPHA &&
                                nextEntry.startOffset == subEntry.endOffset) {
                            // 변경 전 단위명 미리 등록
                            dummy = subEntry.clone();
                            subQueue.add(dummy);

                            // 단위 + 영문 합성텀
                            subEntry.length += nextEntry.length;
                            subEntry.endOffset += nextEntry.length;
                            queue.remove(removeInx);
                            typeContinuous--;
                        }
                    } else {
                        subEntry.type = ALPHANUM;
                    }
                    subEntry.synonym = null;
                    subQueue.add(subEntry);
                } else {
                    subQueue.add(subEntry);
                }
            }
            logger.trace("merge : {}[{}:{}/{}~{}]", subEntry, subEntry.start, subEntry.length, subEntry.startOffset, subEntry.endOffset);
            logger.trace("subQueue : {}", subQueue);
            entry.length = start + length - entry.start;
            entry.endOffset = endOffset;
        }
        entry.type = type;
        queue.add(removeInx, entry);
        return entry;
    }

    protected static RuleEntry mergeQueueQuery(int qinx, int typeContinuous, List<RuleEntry> queue, List<RuleEntry> subQueue) {
        int removeInx = qinx - typeContinuous;
        if (removeInx < 0) {
            removeInx = 0;
            typeContinuous--;
        }

        if (queue.get(removeInx + typeContinuous - 1).type == SYMBOL) {
            typeContinuous--;
        }

        if (typeContinuous == 1) {
            logger.trace("queue has only one entry. so don't merge it");
            return null;
        }

        logger.trace("queue[{}]={}", removeInx + typeContinuous - 1, queue.get(removeInx + typeContinuous - 1));

        RuleEntry entry = queue.get(removeInx).clone();
        logger.trace("ENTRY-CLONE:{}", entry);
        // 클로닝 되기 때문에 동의어를 반드시 삭제 해 주어야 한다.
        if (entry.type == UNIT_ALPHA) {
            entry.synonym = null;
        }
        entry.length = 0;
        entry.endOffset = entry.startOffset;
        String type = entry.type;
        RuleEntry subEntry = null;
        RuleEntry nextEntry = null;
        for (; typeContinuous > 0; typeContinuous--) {
            subEntry = queue.remove(removeInx);
            logger.trace("pop entry:{}/{}:{}[{}~{}] / {}", subEntry, subEntry.start, subEntry.length, subEntry.startOffset, subEntry.endOffset, subEntry.synonym);
            if (type != subEntry.type) {
                type = null;
            }
            int start = subEntry.start;
            int length = subEntry.length;
            int endOffset = subEntry.endOffset;
            if (subQueue != null) {
                if (subEntry.type == UNIT_ALPHA) {
                    // 단위명이었지만 규칙에 의해 모델명으로 전환되는 경우.
                    // 단위명과 숫자를 구분해준다.
                    logger.trace("subList:{}{}", "", subEntry.subEntry);
                    if (subEntry != null && subEntry.subEntry.size() > 0) {
                        RuleEntry number = subEntry.subEntry.remove(0);
                        subQueue.add(number);
                        subEntry.start += number.length;
                        subEntry.length -= number.length;
                        subEntry.startOffset += number.length;
                        subEntry.type = ALPHA;
                        // 단위명 뒤 엔트리가 영문이라면 단위명과 합치도록 한다. (118X71WXU3 -> 71W + XU -> 71 + WXU)
                        if (removeInx < queue.size() &&
                                (nextEntry = queue.get(removeInx)).type == ALPHA &&
                                nextEntry.startOffset == subEntry.endOffset) {
                            subEntry.length += nextEntry.length;
                            subEntry.endOffset += nextEntry.length;
                            queue.remove(removeInx);
                            typeContinuous--;
                        }
                    } else {
                        subEntry.type = ALPHANUM;
                    }
                    subEntry.synonym = null;
                    subQueue.add(subEntry);
                } else {
                    subQueue.add(subEntry);
                }
            }
            logger.trace("merge : {}[{}:{}/{}~{}]", subEntry, subEntry.start, subEntry.length, subEntry.startOffset, subEntry.endOffset);
            logger.trace("subQueue : {}", subQueue);
            entry.length = start + length - entry.start;
            entry.endOffset = endOffset;
        }
        entry.type = type;
        queue.add(removeInx, entry);
        return entry;
    }


    /*
     * 1. 단위명 동의어 처리
     * 2. 변형
     * 3. 서브엔트리
     * */
    public static RuleEntry modifyRuleEntry(boolean fullExtract, AnalyzerOption option, RuleEntry e0, RuleEntry e1,
                                            CharVector unitCandidate, CharSequence[] units,
                                            String unitType) {
        RuleEntry backup = e0.clone();
        if (fullExtract) {
            e0.subEntry = new ArrayList<>();
            e0.subEntry.add(backup);
        }

        CharSequence[] synonyms = null;
        // 색인시 단위명 동의어는 추출하지 않는다
        if (fullExtract && units != null && option.useForQuery()) {
            if (units != null && !(units.length == 1 && unitCandidate.equals(units[0]))) {
                synonyms = new CharVector[units.length];
                for (int inx = 0; inx < units.length; inx++) {
                    char[] ubuf = new char[e0.length + units[inx].length()];
                    CharVector unitInx = CharVector.valueOf(units[inx]);
                    System.arraycopy(e0.buf, e0.start, ubuf, 0, e0.length);
                    System.arraycopy(unitInx.array(), unitInx.offset(), ubuf,
                            e0.length, units[inx].length());
                    synonyms[inx] = new CharVector(ubuf);
                }
            }
        }

        // 변형숫자가 있다면, 일반숫자로 바꾸어 다시한 번 단위명을 산출한다.
        if (e0.type == NUMBER_TRANS) {
            CharVector number = e0.makeTerm(null);
            number = new CharVector(number.toString().replaceAll(",", ""));
            // 변형숫자를 일반숫자로 변경했는데 변경사항이 없다면 동의어를 만들지 않음.
            if (backup.length != number.length()) {
                String unitStr = number + unitCandidate.toString();
                e1 = new RuleEntry(unitStr.toCharArray(), 0, unitStr.length(),
                        e0.startOffset, e0.endOffset + unitCandidate.length(), UNIT);
                e0.subEntry.add(0, e1);
                logger.trace("E0:{}/E1:{}", e0, e1);
            }
        }

        if (fullExtract) {
            if (e0.subEntry == null) {
                e0.subEntry = new ArrayList<>();
            }
            if (synonyms != null && synonyms.length > 0) {
                e0.synonym = synonyms;
            }
        }

        e0.length += unitCandidate.length();
        e0.endOffset += unitCandidate.length();

        if (unitType == ALPHA) {
            e0.type = UNIT_ALPHA;
        } else {
            e0.type = UNIT;
        }

        return e1;
    }

    public static void mergeSubQueue(RuleEntry entry, List<RuleEntry> subQueue, AnalyzerOption option, SetDictionary unitDictionary) {
        if (entry.type == MODEL_NAME) {
            // 바이트 비교가 많으므로 버퍼기준으로 처리하도록 한다.
            boolean processed = false;
            if (subQueue.size() == 3) {
                // 모델명이 3블럭이며, 가운데 기호가 있는 경우, 붙여서만 출력함.
                // 단위명 + 1글자 등의 조합으로 나올수 있으므로 일단 합쳐서 체크하도록 한다.
                int contCnt = 0;
                RuleEntry initEntry = subQueue.get(0).clone();
                RuleEntry prevEntry = initEntry;
                for (int cinx = 1; cinx < subQueue.size(); cinx++, contCnt++) {
                    RuleEntry currentEntry = subQueue.get(cinx);
                    if (prevEntry.startOffset + prevEntry.length != currentEntry.startOffset) {
                        break;
                    }
                    initEntry.length += currentEntry.length;
                    prevEntry = currentEntry;
                }
                // 합칠수 있는 블럭인 경우.
                if (contCnt > 0 && contCnt == subQueue.size() - 1) {
                    if (initEntry.length == 2) {
                        String charType = getType(initEntry.buf[initEntry.start]);
                        String nextCharType = getType(initEntry.buf[initEntry.start + 1]);
                        if ((charType == ALPHA || charType == NUMBER) &&
                                // 모델명이 2블럭이며, 영숫자 + 특수기호 인 경우
                                (nextCharType == SYMBOL)) {
                            entry.length -= 1;
                            entry.endOffset -= 1;
                            entry.type = charType;
                            subQueue.clear();
                            processed = true;
                        } else if ((charType == SYMBOL) &&
                                // 모델명이 2블럭이며, 영숫자 + 특수기호 인 경우
                                (nextCharType == ALPHA || nextCharType == NUMBER)) {
                            entry.start++;
                            entry.startOffset++;
                            entry.length--;
                            entry.type = nextCharType;
                            subQueue.clear();
                            processed = true;
                        } else if (charType != nextCharType &&
                                // 모델명이 2블럭이며, 1글자씩이 붙어서 나온 것이면 붙여서만 출력 한다.
                                (charType == ALPHA || charType == NUMBER) &&
                                (nextCharType == ALPHA || nextCharType == NUMBER)) {
                            subQueue.clear();
                            processed = true;
                        }
                    } else if (initEntry.length == 3) {
                        String charType = getType(initEntry.buf[initEntry.start]);
                        String nextCharType = getType(initEntry.buf[initEntry.start + 1]);
                        String nextNextCharType = getType(initEntry.buf[initEntry.start + 2]);
                        if ((charType == ALPHA || charType == NUMBER) &&
                                (nextCharType == SYMBOL) &&
                                (nextNextCharType == ALPHA || nextNextCharType == NUMBER)) {
                            subQueue.clear();
                        } else if (charType != nextCharType && nextCharType != nextNextCharType &&
                                (charType == ALPHA || charType == NUMBER) &&
                                (nextCharType == ALPHA || nextCharType == NUMBER) &&
                                (nextNextCharType == ALPHA || nextNextCharType == NUMBER)) {
                            subQueue.clear();
                        }
                        processed = true;
                    }
                }
            }
            if (!processed) {
                if (subQueue.size() == 2) {
                    // 모델명이 2블럭이며, 1글자씩이 붙어서 나온 것이면 붙여서만 출력 한다.
                    RuleEntry currentEntry = subQueue.get(0);
                    RuleEntry nextEntry = subQueue.get(1);
                    if (currentEntry.length == 1 && nextEntry.length == 1) {
                        subQueue.clear();
                    } else if (currentEntry.type == SYMBOL) {
                        entry.start += currentEntry.length;
                        entry.startOffset += currentEntry.length;
                        entry.length -= currentEntry.length;
                        entry.type = nextEntry.type;
                    } else if (nextEntry.type == SYMBOL) {
                        entry.length -= nextEntry.length;
                        entry.endOffset -= nextEntry.length;
                        entry.type = currentEntry.type;
                    }
                } else if (subQueue.size() == 3) {
                    RuleEntry currentEntry = subQueue.get(0);
                    RuleEntry nextEntry = subQueue.get(1);
                    RuleEntry nextNextEntry = subQueue.get(2);
                    if (currentEntry.length == 1 && nextEntry.length == 1 && nextNextEntry.length == 1) {
                        // 모델명이 3블럭이며, 가운데 기호가 있는 경우, 붙여서만 출력함.
                        if ((currentEntry.type == ALPHA || currentEntry.type == NUMBER)
                                && (nextNextEntry.type == ALPHA || nextNextEntry.type == NUMBER)) {
                            if (nextEntry.type == SYMBOL) {
                                if (nextEntry.buf[nextEntry.start] != '+') {
                                    subQueue.clear();
                                }
                            } else if (currentEntry.type == nextNextEntry.type) {
                                currentEntry.length += nextEntry.length + nextNextEntry.length;
                                currentEntry.endOffset = nextNextEntry.endOffset;
                                subQueue.remove(2);
                                subQueue.remove(1);
                            }
                        }
                    }
                }
            }

            int continuous = 0;

            logger.trace("subQueue : {}", subQueue);

            // 2014.08.29 1byte 씩 영문자 숫자가 교차되어 발견되는 구간에서 '-' 등의 특수기호로 연결 되어 있다면
            // 교차된 영 숫자는 분리하지 않는다.
            for (int inx = 0; inx <= subQueue.size(); inx++) {
                RuleEntry workingEntry = null;
                if (inx < subQueue.size()) {
                    workingEntry = subQueue.get(inx);
                }
                // 1바이트씩 교차되어 나타나는 영문, 숫자들 1a2b3c....
                if (workingEntry != null && workingEntry.length == 1 && (workingEntry.type == ALPHA || workingEntry.type == NUMBER)) {
                    logger.trace("e0:{} / {}:{}", workingEntry, inx, continuous);
                    continuous++;
                } else if (continuous > 1) {

                    boolean frontMatch = inx > 0 && (inx - continuous) > 0;
                    if (frontMatch) {
                        RuleEntry prevEntry = subQueue.get(inx - continuous - 1);
                        if (!(prevEntry.type == SYMBOL && prevEntry.length == 1)) {
                            frontMatch = false;
                        }
                    }

                    boolean rearMatch = inx > 0 && inx < subQueue.size();

                    if (rearMatch) {
                        RuleEntry nextEntry = subQueue.get(inx);
                        if (!(nextEntry.type == SYMBOL && nextEntry.length == 1)) {
                            rearMatch = false;
                        }
                    }

                    if (inx < subQueue.size()) {
                        logger.trace("inx:{}/{} / continuous:{} / fmatch:{} / rmatch:{} / entry:{}", inx, subQueue.size(), continuous, frontMatch, rearMatch, subQueue.get(inx));
                    }

                    //
                    // 2016.05.13 추가규칙.
                    // 다음과 같은 규칙으로 변경
                    /**
                     * 1b-12345	(1b 1 b 12345 1b-12345) -> I/Q(1b 12345 1b-12345)
                     * b1/a2s	(b1 b 1 a 2 s a2s b1/a2s) -> I/Q(b1 a 2 s a2s b1/a2s)
                     * c9-123567	(c9 c 9 123567 9123567 c9-123567) -> I(c9 123567 9123567 c9-123567)/Q(c9 123567 c9-123567)
                     * d9-b	(d9 d 9 b d9-b) -> I/Q(d9 b db-b)
                     * d8-1	(d8 d 8 1 81 d8-1) -> I(d8 1 81 d8-1)/Q(d8 1 d8-1)
                     * 1b/a2s	(1b 1 b a ba 2 s a2s 1b/a2s) -> I(1b a ba 2 s a2s 1b/a2s)/Q(1b a 2 s a2s 1b/a2s)
                     * 9c-abcdef	(9c 9 c abcdef cabcdef 9c-abcdef) -> I(9c abcdef cabcdef 9c-abcdef)/Q(9c abcdef 9c-abcdef)
                     * 8a/b	(8a 8 a b ab 8a/b) -> I(8a b ab 8a/b)/Q(8a b 8a/b)
                     * 7b-3	(7b 7 b 3 7b-3) -> I(7b 3 7b-3)/Q(7b 3 7b-3)
                     * 1A-B2C3D4	(1A 1 A B AB 2 C 3 D 4 B2C3D4 1A-B2C3D4) -> I(1A B AB 2 C 3 D 4 B2C3D4 1A-B2C3D4)/Q(1A B 2 C 3 D 4 B2C3D4 1A-B2C3D4)
                     * I7-4700MQ (2.4GHZ)	(I7 I 7 4700 74700 MQ I7-4700MQ 2.4 2.4GHZ) -> I(I7 4700 74700 MQ I7-4700MQ 2.4 2.4GHZ)/Q(I7 4700 MQ I7-4700MQ 2.4 2.4GHZ)
                     * AKSO-1X	(AKSO 1 X 1X AKSO-1X) -> I/Q(AKSO 1X AKSO-1X)
                     * AKSO-1G	(AKSO 1 G 1G AKSO-1G) -> I/Q(AKSO 1G AKSO-1G)
                     * Z9PE-D8 WS STCOM	(Z 9 PE D PED 8 D8 WS STCOM) -> I(Z 9 PE D8 PED WS STCOM)/Q(Z 9 PE D8 WS STCOM)
                     * 어답터/DC/AC/출력1.5V/2V/3V/4.5V/5V/7.5V/9V/600MA/충전기	(어답터 DC AC DCAC DC/AC 출력 1.5 V 2 V 2V 3 V 3V 4.5 V 5 V 5V 7.5 V 9 V 9V 600 MA 1.5V/2V/3V/4.5V/5V/7.5V/9V/600MA 충전기) -> I(어답터 DC AC DCAC DC/AC 출력 1.5 V 2V 3V 4.5 V 5V 7.5 V 9V 600 MA 1.5V/2V/3V/4.5V/5V/7.5V/9V/600MA 충전기)/Q(어답터 DC AC DC/AC 출력 1.5 V 2V 3V 4.5 V 5V 7.5 V 9V 600 MA 1.5V/2V/3V/4.5V/5V/7.5V/9V/600MA 충전기)
                     */

                    // 색인전용 규칙으로 되어 있던 텀 병합 루틴을 질의용으로도 사용하고, 분리된 글자를 지우지 않던 기존 규칙을 다시 취소함.
                    // 영숫자 앞 혹은 뒤에 특수문자로 연결되어 있다면.
                    if (option.useForQuery() && ((inx - continuous == 0 && rearMatch)
                            || (frontMatch && inx == subQueue.size())
                            || frontMatch && rearMatch)) {
                        int pos = inx - continuous;
                        RuleEntry currentEntry = subQueue.get(pos).clone();
                        currentEntry.length += continuous - 1;
                        // 붙여서 출력해주기 위해 subentry 들을 삭제.
                        // 2016.05.13 교차영숫자 체크를 전구간으로 확대하되 3글자 이하에서만 체크하도록 함.
                        // if (pos == 0 || !option.isForDocument())
                        if (continuous < 3) {
                            for (int subInx = 0; subInx < continuous; subInx++) {
                                // 2016.05.13 규칙에 의해 변경됨. 교차영숫자 머징 후 분리된글자는 삭제
                                // 2014.12.29 1byte 씩 교차된 영 숫자는 분리하지 않는다
                                // 삭제: ---분리된 글자는 지우지 않고 같이 출력하도록 한다.---
                                RuleEntry nextEntry = subQueue.get(pos + subInx);
                                subQueue.remove(pos + subInx);
                                currentEntry.subEntry.add(nextEntry);
                                logger.trace("remove entry : {} , C:{}/{}/{}", nextEntry, continuous, subInx, inx);

                                continuous--;
                                subInx--;
                                inx--;
                            }
                        }

                        currentEntry.type = ALPHANUM;
                        currentEntry.endOffset += currentEntry.length - 1;
                        if (frontMatch && rearMatch) {
                            subQueue.add(pos + continuous, currentEntry);
                        } else if (frontMatch) {
                            subQueue.add(pos + continuous, currentEntry);
                        } else if (rearMatch) {
                            subQueue.add(pos, currentEntry);
                        }
                        logger.trace("entry : {}", currentEntry);
                        inx -= continuous;
                    }
                    continuous = 0;
                } else {
                    continuous = 0;
                }
            }

            logger.trace("subQueue : {}", subQueue);

            if (option.useForQuery()) {
                for (int inx = 0; inx < (subQueue.size() - 1); inx++) {
                    RuleEntry currentEntry = subQueue.get(inx);
                    RuleEntry nextEntry = subQueue.get(inx + 1);
                    RuleEntry prevEntry = null;
                    RuleEntry nextNextEntry = null;
                    if (inx > 0) {
                        prevEntry = subQueue.get(inx - 1);
                    }
                    if ((inx + 2) < subQueue.size()) {
                        nextNextEntry = subQueue.get(inx + 2);
                    }
                    if (((prevEntry == null || (prevEntry.type == SYMBOL && prevEntry.start + prevEntry.length == currentEntry.start))
                            && (currentEntry.type == ALPHA && nextEntry.type == NUMBER && (currentEntry.start + currentEntry.length == nextEntry.start))
                            && (currentEntry.length == 1 && nextEntry.length == 1)
                            && (nextNextEntry == null || (nextNextEntry.type == SYMBOL && nextEntry.start + nextEntry.length == nextNextEntry.start)))) {

                        if (logger.isTraceEnabled()) {
                            logger.trace("================================================================================");
                            logger.trace("entry : {}{} // I:{} / C:{} / F:{} / R:{} / Q:{}", currentEntry.makeTerm(null), nextEntry.makeTerm(null), inx);
                            logger.trace("================================================================================");
                        }

                        currentEntry.length++;
                        currentEntry.type = ALPHANUM;
                        subQueue.remove(inx + 1);
                    }
                }
            }

            logger.trace("subQueue : {}", subQueue);
            List<RuleEntry> tmpList = new ArrayList<>();

            for (int inx = 0; inx < subQueue.size(); inx++) {
                RuleEntry currentEntry = subQueue.get(inx);
                if (currentEntry.type == SYMBOL) {
                    char c = currentEntry.buf[currentEntry.start];
                    if (c == '-' || c == '_' || c == '/') {
                        // 모델명 중 영문 특수문자(-/) 숫자 조합인 경우 첫 영문 형태소를 제외한 모델명도 추출
                        // 모델명이 모두 추가텀으로 바뀌어야 하기 때문에 이 쪽은 모두 추가텀으로 돌리도록 한다.
                        // 2014.09.02 특수규칙. 영숫자가 번갈아 가며 나온 경우 (ALPHANUM) 와 겹치는 규칙이 있으므로
                        // 체크해서 지워준다.
                        if (!option.useForQuery()) {
                            if (inx == 1 && inx + 2 < subQueue.size()) {
                                RuleEntry prevEntry = subQueue.get(inx - 1);
                                RuleEntry nextEntry = subQueue.get(inx + 1);
                                RuleEntry nextNextEntry = subQueue.get(inx + 2);
                                RuleEntry lastEntry = subQueue.get(subQueue.size() - 1);
                                if (!(lastEntry.start == nextEntry.start && lastEntry.type == ALPHANUM)) {
                                    if (prevEntry.length > 0 && nextEntry.start > (prevEntry.start + prevEntry.length)
                                            && nextNextEntry.start == (nextEntry.start + nextEntry.length)
                                            && prevEntry.type == ALPHA
                                            && ((nextEntry.type == ALPHA && nextNextEntry.type == NUMBER)
                                            || (nextEntry.type == NUMBER && nextNextEntry.type == ALPHA))) {
                                        RuleEntry newEntry = new RuleEntry(nextEntry.buf, nextEntry.start, lastEntry.start + lastEntry.length - nextEntry.start, nextEntry.startOffset, lastEntry.endOffset, MODEL_NAME);
                                        logger.trace("QUEUE : {}", subQueue);
                                        logger.trace("NEW-ENTRY : {}", newEntry);
                                        tmpList.add(newEntry);
                                    }
                                } else {
                                    logger.trace("remove duplicated term : {}", lastEntry);
                                }
                            }
                        }

                        if (inx > 0 && inx + 1 < subQueue.size()) {
                            RuleEntry prevEntry = subQueue.get(inx - 1);
                            RuleEntry nextEntry = subQueue.get(inx + 1);
                            if (!option.useForQuery()) {
                                // 색인때에만
                                // 모델명 중 숫자블럭 사이, 혹은 문자블럭 사이에 특수문자 가 있다면
                                // 각각의 숫자, 혹은 문자 와 특수문자를 제거한 조합도 출력한다.
                                int checkLevel = 0;
                                if (nextEntry.startOffset == prevEntry.endOffset + 1) {
                                    if (prevEntry.type == MODEL_NAME || prevEntry.type == ALPHANUM) {
                                        if (nextEntry.type == ALPHA || nextEntry.type == NUMBER || nextEntry.type == ALPHANUM || nextEntry.type == MODEL_NAME) {
                                            checkLevel = 2;
                                        }
                                    } else if (nextEntry.type == MODEL_NAME || nextEntry.type == ALPHANUM) {
                                        if (prevEntry.type == ALPHA || prevEntry.type == NUMBER || prevEntry.type == ALPHANUM || prevEntry.type == MODEL_NAME) {
                                            checkLevel = 2;
                                        }
                                    } else {
                                        if (prevEntry.type == ALPHA || prevEntry.type == NUMBER) {
                                            if (prevEntry.type == nextEntry.type) {
                                                checkLevel = 3;
                                            }
                                        }
                                    }
                                }
                                if (checkLevel == 2) {
                                    // 앞단어 맨 뒤의 글자타입과 뒷단어 맨 첫번째의 글자타입이 같다면 수행
                                    String lastCharTypeOfPrevEntry = getType(prevEntry.buf[prevEntry.start + prevEntry.length - 1]);
                                    String firstCharTypeOfNextEntry = getType(nextEntry.buf[nextEntry.start]);
                                    if (lastCharTypeOfPrevEntry == firstCharTypeOfNextEntry) {
                                        // 같은 타입만 잘라낸다.
                                        // 둘중 하나가 모델명 이었다면, 같은 타입의 부분만 잘라 내야 한다.
                                        int newPrevEntryLength = 0;
                                        for (int sinx = prevEntry.length; sinx > 0; sinx--) {
                                            if (getType(prevEntry.buf[prevEntry.start + sinx - 1]) == lastCharTypeOfPrevEntry) {
                                                newPrevEntryLength++;
                                            } else {
                                                break;
                                            }
                                        }
                                        // 조정된 길이로 prevEntry 새로 셋팅.
                                        RuleEntry tmpEntry = prevEntry.clone();
                                        tmpEntry.start += (prevEntry.length - newPrevEntryLength);
                                        tmpEntry.startOffset += (prevEntry.length - newPrevEntryLength);
                                        tmpEntry.length = newPrevEntryLength;
                                        tmpEntry.endOffset = tmpEntry.startOffset + newPrevEntryLength;
                                        tmpEntry.type = lastCharTypeOfPrevEntry;
                                        prevEntry = tmpEntry;

                                        int newNextEntryLength = 0;
                                        for (int sinx = 0; sinx < nextEntry.length; sinx++) {
                                            if (getType(nextEntry.buf[nextEntry.start + sinx]) == firstCharTypeOfNextEntry) {
                                                newNextEntryLength++;
                                            } else {
                                                break;
                                            }
                                        }
                                        // 조정된 길이로 nextEntry 새로 셋팅.
                                        RuleEntry tmpEntry2 = nextEntry.clone();
                                        tmpEntry2.length = newNextEntryLength;
                                        tmpEntry2.endOffset = tmpEntry2.startOffset + newNextEntryLength;
                                        tmpEntry2.type = firstCharTypeOfNextEntry;
                                        nextEntry = tmpEntry2;
                                        checkLevel = 3;
                                    }
                                }
                                if (checkLevel == 3) {
                                    // 원본변형이 일어나기 때문에 버퍼는 따로 잡아 주어야 한다.
                                    RuleEntry clone = prevEntry.clone();
                                    char[] buf = new char[prevEntry.length + nextEntry.length];
                                    System.arraycopy(prevEntry.buf, prevEntry.start, buf, 0, prevEntry.length);
                                    System.arraycopy(nextEntry.buf, nextEntry.start, buf, prevEntry.length, nextEntry.length);
                                    clone.buf = buf;
                                    clone.start = 0;
                                    clone.length = buf.length;
                                    clone.startOffset = prevEntry.startOffset;
                                    clone.endOffset = nextEntry.endOffset;
                                    logger.trace("TRANS-MERGE:{} / {} / {}", clone, currentEntry, prevEntry);
                                    tmpList.add(clone);
                                }
                            }
                        }
                    }
                    // 개별 특수문자는 모두 제거한다.
                    subQueue.remove(inx);
                    inx--;
                } else if (currentEntry.type == UNIT_ALPHA) {
                    // 단위명이었지만 규칙에 의해 모델명으로 전환되는 경우.
                    // 단위명과 숫자를 구분해준다.
                    logger.trace("subList:{}{}", "", currentEntry.subEntry);
                    if (currentEntry.subEntry != null && currentEntry.subEntry.size() > 0) {
                        RuleEntry e1 = currentEntry.subEntry.remove(0);
                        tmpList.add(e1);
                        currentEntry.start += e1.length;
                        currentEntry.length -= e1.length;
                        currentEntry.type = ALPHA;
                    } else {
                        currentEntry.type = ALPHANUM;
                    }
                    currentEntry.synonym = null;
                } else if (currentEntry.type == ALPHA) {
                    // 강제분해 등으로 붙지 못한 영문자 끼리 이어준다.
                    if (inx + 1 < subQueue.size()) {
                        RuleEntry e1 = subQueue.get(inx + 1);
                        if (e1.startOffset == currentEntry.endOffset + 1 && e1.type == ALPHA) {
                            currentEntry.length += e1.length;
                            currentEntry.endOffset = e1.endOffset;
                            subQueue.remove(inx + 1);
                        }
                    }
                }
            }

            logger.trace("subQueue : {}", subQueue);

            if (subQueue.size() > 2) {
                RuleEntry currentEntry = subQueue.get(0);
                RuleEntry nextEntry = subQueue.get(1);
                logger.trace("TERM:{}/{}", nextEntry.start, nextEntry.length);
                String finalType = getType(nextEntry.buf[nextEntry.start + nextEntry.length - 1]);
                // 모델명 맨 앞의 두 바이트가 타입이 틀리고 뒤에 기호가 나오면 붙여준다.
                if (nextEntry.start == currentEntry.start + currentEntry.length &&
                        currentEntry.length == 1 && nextEntry.length == 1 && finalType == SYMBOL
                        && ((currentEntry.type == NUMBER && nextEntry.type == ALPHA)
                        || (currentEntry.type == ALPHA && nextEntry.type == NUMBER))) {
                    subQueue.remove(1);
                    currentEntry.length += nextEntry.length;
                    currentEntry.endOffset = currentEntry.startOffset + currentEntry.length + nextEntry.length;
                    currentEntry.type = MODEL_NAME;
                }
            }

            if (!option.useForQuery()) {
                // 추가 텀 추출
                exportByTriGram(subQueue, tmpList);
                // 단위명 추가 텀 추출
                exportUnitGram(subQueue, tmpList, unitDictionary);
            }

            if (tmpList.size() > 0) {
                subQueue.addAll(tmpList);
            }
            ////////////////////////////////////////////////////////////////////////////////
            Collections.sort(subQueue);
        }
    }

    private static void exportByTriGram(List<RuleEntry> subQueue, List<RuleEntry> tmpList) {
        Iterator<RuleEntry> iter = subQueue.iterator();
        RuleEntry currentEntry = null;
        RuleEntry nextEntry = null;

        while (iter.hasNext()) {
            if (currentEntry == null) {
                currentEntry = iter.next();
            }

            RuleEntry nextNextEntry;

            if (currentEntry.length == 1 && ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start]))) || currentEntry.type == NUMBER)) {
                // 다음 엔트리를 불러온다
                if (iter.hasNext() && nextEntry == null) {
                    nextEntry = iter.next();

                    // 현재와 다음 엔트리를 비교 및 결합한다
                    if (isConnected(currentEntry, nextEntry)) {
                        combineNextEntry(tmpList, currentEntry, nextEntry, ALPHANUM);
                    }
                }

                // 현재와 다음, 다다음 엔트리를 비교 및 결합한다
                if (nextEntry != null && nextEntry.length == 1 && ((nextEntry.type == ALPHA || (nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start]))) || nextEntry.type == NUMBER)) {
                    if ((currentEntry.type == NUMBER && (nextEntry.type == ALPHA || (nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start]))) || ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start]))) && nextEntry.type == NUMBER))) {
                        // 다다음 엔트리를 불러온다
                        if (iter.hasNext()) {
                            nextNextEntry = iter.next();

                            // 다다음 엔트리까지 확인해서 결합한다
                            if (isConnected(currentEntry, nextEntry) && isConnected(nextEntry, nextNextEntry)) {
                                if (nextNextEntry != null && nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start])) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start])))) {
                                    combineNextNextEntry(tmpList, currentEntry, nextEntry, nextNextEntry, ALPHANUM);
                                }
                            } else if (isConnected(nextEntry, nextNextEntry)) {
                                if (nextNextEntry != null && nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start])) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start])))) {
                                    combineNextNextEntry(tmpList, nextEntry, nextNextEntry, ALPHANUM);
                                }
                            }

                            // 읽은 곳까지 기록한다
                            currentEntry = nextEntry;
                            nextEntry = nextNextEntry;
                        }
                    } else {
                        // 영문, 숫자 1 바이트가 아니라면 다음 엔트리로 이동한다.
                        currentEntry = nextEntry;
                        nextEntry = null;
                    }
                } else if (iter.hasNext()) {
                    // 영문, 숫자 1 바이트가 아니라면 다음 엔트리로 이동한다.
                    currentEntry = nextEntry;
                    nextEntry = null;
                }
            } else if (iter.hasNext()) {
                // 영문, 숫자 1 바이트가 아니라면 다음 엔트리로 이동한다.
                currentEntry = iter.next();
            }
        }
    }

    private static void exportUnitGram(List<RuleEntry> subQueue, List<RuleEntry> tmpList, SetDictionary unitDictionary) {
        Iterator<RuleEntry> iter = subQueue.iterator();
        RuleEntry currentEntry = null;

        while (iter.hasNext()) {
            // init
            if (currentEntry == null) {
                currentEntry = iter.next();
            }

            if (iter.hasNext()) {
                RuleEntry nextEntry = iter.next();

                // 이미 결합됨
                if (currentEntry.length == 1 && nextEntry.length == 1) {
                    currentEntry = nextEntry;
                    continue;
                }

                CharVector unitCandidate = new CharVector();
                unitCandidate.init(nextEntry.buf, nextEntry.start, nextEntry.length);

                if (unitDictionary != null && unitDictionary.set().contains(unitCandidate)) {
                    nextEntry.type = UNIT;
                }

                if (currentEntry.type == NUMBER && (nextEntry.type == UNIT || nextEntry.type == UNIT_ALPHA)) {
                    // 현재와 다음 엔트리를 비교 및 결합한다
                    combineNextUnitEntry(tmpList, currentEntry, nextEntry, UNIT);
                }
                currentEntry = nextEntry;
            }
        }
    }


    private static void combineNextNextEntry(List<RuleEntry> tmpList, RuleEntry nextEntry, RuleEntry nextNextEntry, String type) {
        if (nextNextEntry != null && nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start])) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start])))) {
            tmpList.add(mergeNewEntry(nextEntry, nextNextEntry, type));
        }
    }

    private static void combineNextNextEntry(List<RuleEntry> tmpList, RuleEntry currentEntry, RuleEntry nextEntry, RuleEntry nextNextEntry, String type) {
        if (nextNextEntry != null && nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start])) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start])))) {
            tmpList.add(mergeNewEntry(nextEntry, nextNextEntry, type));
            tmpList.add(mergeNewEntry(currentEntry, nextEntry, nextNextEntry, type));
        }
    }

    private static void combineNextEntry(List<RuleEntry> tmpList, RuleEntry currentEntry, RuleEntry nextEntry, String type) {
        if (nextEntry != null && nextEntry.length == 1 && ((nextEntry.type == ALPHA || currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start])) || nextEntry.type == NUMBER)) {
            if ((currentEntry.type == NUMBER && (nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start]))) || ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start]))) && nextEntry.type == NUMBER)) {
                tmpList.add(mergeNewEntry(currentEntry, nextEntry, type));
            }
        }
    }

    private static void combineNextUnitEntry(List<RuleEntry> tmpList, RuleEntry currentEntry, RuleEntry nextEntry, String type) {
        if (nextEntry != null && currentEntry.type == NUMBER && nextEntry.type == UNIT) {
            tmpList.add(mergeNewEntry(currentEntry, nextEntry, type));
        }
    }
}

